"use client";

import { useEffect, useState, useCallback } from "react";
import { ChevronLeft, ChevronRight, ExternalLink, History, ShieldAlert, UserCheck } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { getPositions } from "@/lib/api";
import { formatAddress, formatRelativeTime, formatUsd } from "@/lib/format";
import type { SimPosition } from "@/lib/types";

type Props = { address: string };

export function ClosedPositionsTable({ address }: Props) {
  const [positions, setPositions] = useState<SimPosition[]>([]);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(true);

  const load = useCallback(
    async (targetPage: number) => {
      setLoading(true);
      try {
        const res = await getPositions(address, "closed", targetPage, 20);
        setPositions(res.positions);
        setTotalPages(Math.max(1, res.totalPages));
      } finally {
        setLoading(false);
      }
    },
    [address]
  );

  useEffect(() => {
    load(page);
  }, [load, page]);

  return (
    <Card className="border-border/60">
      <CardHeader className="flex flex-row items-center justify-between">
        <CardTitle className="flex items-center gap-2 text-base">
          <History className="size-4 text-primary" /> Closed trades
        </CardTitle>
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          <Button
            variant="outline"
            size="icon"
            className="size-7"
            disabled={page <= 1 || loading}
            onClick={() => setPage((p) => Math.max(1, p - 1))}
          >
            <ChevronLeft className="size-3.5" />
          </Button>
          <span className="tabular-nums">
            {page} / {totalPages}
          </span>
          <Button
            variant="outline"
            size="icon"
            className="size-7"
            disabled={page >= totalPages || loading}
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
          >
            <ChevronRight className="size-3.5" />
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        {loading && positions.length === 0 ? (
          <div className="flex flex-col gap-2">
            {Array.from({ length: 4 }).map((_, i) => (
              <Skeleton key={i} className="h-10 w-full" />
            ))}
          </div>
        ) : positions.length === 0 ? (
          <div className="flex flex-col items-center gap-2 rounded-lg border border-dashed border-border/60 py-10 text-center text-sm text-muted-foreground">
            No closed trades yet
          </div>
        ) : (
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Mint</TableHead>
                  <TableHead className="text-right">Cost basis</TableHead>
                  <TableHead className="text-right">Proceeds</TableHead>
                  <TableHead className="text-right">Realized P&amp;L</TableHead>
                  <TableHead>Closed by</TableHead>
                  <TableHead className="text-right">Closed</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {positions.map((position) => {
                  const pnlPositive = (position.realizedPnlUsd || 0) > 0;
                  const pnlNegative = (position.realizedPnlUsd || 0) < 0;
                  const isStopLoss = position.closeReason === "stop_loss";
                  return (
                    <TableRow key={position._id}>
                      <TableCell>
                        <a
                          href={`https://pump.fun/coin/${position.mint}`}
                          target="_blank"
                          rel="noreferrer"
                          className="inline-flex items-center gap-1 font-mono text-xs text-muted-foreground hover:text-primary"
                        >
                          {formatAddress(position.mint, 5)}
                          <ExternalLink className="size-3" />
                        </a>
                      </TableCell>
                      <TableCell className="text-right tabular-nums">{formatUsd(position.costBasisUsd)}</TableCell>
                      <TableCell className="text-right tabular-nums">{formatUsd(position.proceedsUsd)}</TableCell>
                      <TableCell className="text-right tabular-nums">
                        <span
                          className={[
                            "inline-flex flex-col items-end",
                            pnlPositive && "text-positive",
                            pnlNegative && "text-negative",
                          ]
                            .filter(Boolean)
                            .join(" ")}
                        >
                          <span>{formatUsd(position.realizedPnlUsd)}</span>
                          <span className="text-[11px] opacity-80">
                            {position.realizedPnlPercent !== null ? `${position.realizedPnlPercent.toFixed(1)}%` : "-"}
                          </span>
                        </span>
                      </TableCell>
                      <TableCell>
                        <Badge
                          variant="outline"
                          className={
                            isStopLoss
                              ? "gap-1 border-negative/30 text-negative"
                              : "gap-1 border-border/60 text-muted-foreground"
                          }
                        >
                          {isStopLoss ? <ShieldAlert className="size-3" /> : <UserCheck className="size-3" />}
                          {isStopLoss ? "Stop-loss" : "Trader sold"}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right text-xs text-muted-foreground">
                        {formatRelativeTime(position.closedAt)}
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        )}
      </CardContent>
    </Card>
  );
}
